    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(address user, uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);
        address oldSelf = msg.sender;
        // deposit as 'user' is not possible (msg.sender is this), so deposit for self and check for both self and an untouched address
        c.addToBalance{value: amount}(); if (__ESBMC_reverted()) return;
        uint balUser = c.getBalance(user); if (__ESBMC_reverted()) return;
        uint balSelf = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint contractEth = address(c).balance;
        assert(balSelf <= contractEth && balUser <= contractEth);
    }
    receive() external payable {}
}

